test('lineDiscount calculates discount amount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 2, unitPrice: 8500, discountPercent: 50 }), 8500);
