test('invoiceTotals includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500 + 1 * 9500;
  const discount = Math.round(2 * 8500 * 0.1 + 1 * 9500 * 0.2);
